CREATE TYPE "AnnouncementAudience" AS ENUM ('ALL', 'TEACHERS', 'STUDENTS', 'PARENTS', 'CLASS');
CREATE TABLE "ReportCard" ("id" UUID NOT NULL, "schoolId" UUID NOT NULL, "studentId" UUID NOT NULL, "semesterId" UUID NOT NULL, "gpa" DOUBLE PRECISION NOT NULL, "average" DOUBLE PRECISION NOT NULL, "payload" JSONB NOT NULL, "generatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ReportCard_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Announcement" ("id" UUID NOT NULL, "schoolId" UUID NOT NULL, "title" TEXT NOT NULL, "content" TEXT NOT NULL, "audience" "AnnouncementAudience" NOT NULL DEFAULT 'ALL', "classSectionId" UUID, "publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "expiresAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "deletedAt" TIMESTAMP(3), CONSTRAINT "Announcement_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ReportCard_studentId_semesterId_key" ON "ReportCard"("studentId","semesterId"); CREATE INDEX "ReportCard_schoolId_semesterId_idx" ON "ReportCard"("schoolId","semesterId"); CREATE INDEX "Announcement_schoolId_publishedAt_idx" ON "Announcement"("schoolId","publishedAt");
ALTER TABLE "ReportCard" ADD CONSTRAINT "ReportCard_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ReportCard" ADD CONSTRAINT "ReportCard_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "ReportCard" ADD CONSTRAINT "ReportCard_semesterId_fkey" FOREIGN KEY ("semesterId") REFERENCES "Semester"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Announcement" ADD CONSTRAINT "Announcement_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Announcement" ADD CONSTRAINT "Announcement_classSectionId_fkey" FOREIGN KEY ("classSectionId") REFERENCES "ClassSection"("id") ON DELETE SET NULL ON UPDATE CASCADE;
